  { code: 'es', label: 'Spanish', native: 'Español', flag: '🇪🇸' },
];

export const LanguageProvider = ({ children }) => {
  const [currentLang, setCurrentLang] = useState(() => {
    return localStorage.getItem('agrisense_lang') || 'en';
  });

  useEffect(() => {
    localStorage.setItem('agrisense_lang', currentLang);
    document.documentElement.lang = currentLang;
  }, [currentLang]);

  // Nested translation helper with fallback
  const t = (path) => {
    const keys = path.split('.');

    // Look up in current language
    let value = translations[currentLang];
    for (const key of keys) {
      if (value && typeof value === 'object' && key in value) {
        value = value[key];
      } else {
        value = undefined;
        break;
      }
    }

    // Fallback to English if not found
    if (value === undefined) {
      let fallbackValue = translations['en'];
      for (const key of keys) {
        if (fallbackValue && typeof fallbackValue === 'object' && key in fallbackValue) {
          fallbackValue = fallbackValue[key];
        } else {
          return path; // Return key path if missing
        }
      }
      return fallbackValue;
    }

    return value;
  };

  return (
    <LanguageContext.Provider value={{ currentLang, setCurrentLang, t, languages }}>
      {children}
